package net.reldo.taskstracker.data;

import com.google.gson.annotations.Expose;
import java.time.Instant;
import java.util.HashMap;
import java.util.List;
import lombok.Getter;
import net.reldo.taskstracker.data.task.ConfigTaskSave;
import net.reldo.taskstracker.data.task.ITask;
import net.reldo.taskstracker.data.task.ITaskType;
import net.reldo.taskstracker.quests.DiaryData;
import net.reldo.taskstracker.quests.QuestData;
import net.runelite.api.Actor;
import net.runelite.api.Client;

@Getter
public class Export
{
	private final Client client;

	@Expose
	private final QuestData quests;
	@Expose
	private final DiaryData diaries;
	@Expose
	private String displayName;
	@Expose
	private final int runescapeVersion;
	@Expose
	private final String runeliteVersion;
	@Expose
	private final long timestamp;
	@Expose
	private final String taskType;
	@Expose
	private final HashMap<Integer, Integer> varbits;
	@Expose
	private final HashMap<Integer, Integer> varps;
	@Expose
	private final HashMap<String, ConfigTaskSave> tasks;

	public Export(ITaskType taskType, List<ITask> tasks, String runeliteVersion, Client client)
	{
		this.client = client;
		Actor localPlayer = client.getLocalPlayer();
		if (localPlayer != null)
		{
			this.displayName = localPlayer.getName();
		}
		quests = new QuestData(client);
		diaries = new DiaryData(client);
		runescapeVersion = client.getRevision();
		this.runeliteVersion = runeliteVersion;
		timestamp = Instant.now().toEpochMilli();
		this.taskType = taskType.getTaskJsonName();
		varbits = getVarbits(taskType);
		varps = getVarps(taskType);
		this.tasks = getTaskSavesById(tasks);
	}

	private HashMap<Integer, Integer> getVarbits(ITaskType taskType)
	{
		assert client.isClientThread();

		HashMap<Integer, Integer> varbitValueMap = new HashMap<>();
		for (int varbitId : taskType.getVarbits())
		{
			varbitValueMap.put(varbitId, client.getVarbitValue(varbitId));
		}

		return varbitValueMap;
	}

	public HashMap<Integer, Integer> getVarps(ITaskType taskType)
	{
		assert client.isClientThread();

		HashMap<Integer, Integer> varpValueMap = new HashMap<>();
		for (int varpId : taskType.getTaskVarps())
		{
			varpValueMap.put(varpId, client.getVarpValue(varpId));
		}
		for (int varpId : taskType.getOtherVarps())
		{
			varpValueMap.put(varpId, client.getVarpValue(varpId));
		}

		return varpValueMap;
	}

	public HashMap<String, ConfigTaskSave> getTaskSavesById(List<ITask> tasks)
	{
		HashMap<String, ConfigTaskSave> taskSavesById = new HashMap<>();
		for (ITask task : tasks)
		{
			if (task.getCompletedOn() == 0 && task.getIgnoredOn() == 0 && task.getTrackedOn() == 0)
			{
				continue;
			}
			taskSavesById.put(String.valueOf(task.getTaskId()), task.getSaveData());
		}
		return taskSavesById;
	}
}

package net.reldo.taskstracker.data;

import java.util.Collection;
import lombok.extern.slf4j.Slf4j;
import net.reldo.taskstracker.data.task.ITask;
import net.reldo.taskstracker.data.task.filters.FilterMatcher;
import net.reldo.taskstracker.data.task.filters.TextMatcher;

@Slf4j
public class TasksSummary
{
	// Tracked totals
	public int trackedTasksCount = 0;
	public int trackedTasksPoints = 0;

	// Filtered totals (tasks matching users current filter criteria)
	public int filteredTasksCount = 0;
	public int filteredTasksPoints = 0;

	// Tracked progress breakdown
	public int trackedCompletedCount = 0;
	public int trackedCompletedPoints = 0;
	public int trackedIncompleteCount = 0;
	public int trackedIncompletePoints = 0;

	// Total completed (all tasks, not just tracked) - for tier calculation
	public int totalCompletedCount = 0;
	public int totalCompletedPoints = 0;

	public TasksSummary(Collection<ITask> tasks)
	{
		tasks.forEach(task -> {
			if (task.isTracked())
			{
				trackedTasksCount++;
				int points = task.getPoints();
				log.debug("TasksSummary {} {}", task.getName(), points);
				trackedTasksPoints += points;
			}
		});
	}

	/**
	 * New constructor - calculates filtered totals, tracked progress, and total completed.
	 *
	 * @param tasks         All tasks to process
	 * @param filterMatcher The filter matcher to determine which tasks pass current filters
	 * @param textMatcher   The text matcher for search filtering (can be null)
	 */
	public TasksSummary(Collection<ITask> tasks, FilterMatcher filterMatcher, TextMatcher textMatcher)
	{
		tasks.forEach(task -> {
			int points = task.getPoints();

			// Calculate filtered totals
			if (filterMatcher.meetsFilterCriteria(task, textMatcher))
			{
				filteredTasksCount++;
				filteredTasksPoints += points;
			}

			// Calculate total completed
			if (task.isCompleted())
			{
				totalCompletedCount++;
				totalCompletedPoints += points;
			}

			// Calculate tracked totals with completion breakdown
			if (task.isTracked())
			{
				trackedTasksCount++;
				trackedTasksPoints += points;

				if (task.isCompleted())
				{
					trackedCompletedCount++;
					trackedCompletedPoints += points;
				}
				else
				{
					trackedIncompleteCount++;
					trackedIncompletePoints += points;
				}
			}
		});
	}

	public String formatChatMessage(String taskTypeName, boolean untrackUponCompletion)
	{
		StringBuilder message = new StringBuilder("Task Tracker: ");

		// Pt 1 - Filtered tasks count
		if (filteredTasksCount == 0)
		{
			message.append("No tasks match filter");
		}
		else
		{
			String taskWord = filteredTasksCount == 1 ? "task" : "tasks";
			message.append(String.format("%d filtered %s (%s)",
				filteredTasksCount,
				taskWord,
				formatPoints(filteredTasksPoints)));
		}

		message.append(" | ");

		// Pt 2 - Tracked tasks progress
		if (trackedTasksCount == 0)
		{
			message.append("No tracked tasks");
		}
		else if (untrackUponCompletion)
		{
			message.append(String.format("%d tracked tasks left, worth %s",
				trackedIncompleteCount,
				formatPoints(trackedIncompletePoints)));
		}
		else if (trackedCompletedCount == trackedTasksCount)
		{
			message.append("All tracked tasks done");
		}
		else
		{
			message.append(String.format("%d of %d tracked tasks left (%s)",
				trackedIncompleteCount,
				trackedTasksCount,
				formatPoints(trackedIncompletePoints)));
		}

		return message.toString();
	}

	// Pluralization
	private String formatPoints(int points)
	{
		return points == 1 ? "1 pt" : points + " pts";
	}
}

package net.reldo.taskstracker.data;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.google.gson.reflect.TypeToken;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.UUID;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.reldo.taskstracker.TasksTrackerPlugin;
import net.reldo.taskstracker.config.ConfigValues;
import net.reldo.taskstracker.data.gson.GsonFactory;
import net.reldo.taskstracker.data.route.CustomRoute;
import net.reldo.taskstracker.data.task.TaskService;
import net.runelite.client.config.ConfigManager;

@Singleton
@Slf4j
public class TrackerGlobalConfigStore
{
	public static final String CONFIG_TASKS_PREFIX = ConfigValues.CONFIG_TASKS_PREFIX;
	public static final String CONFIG_GROUP_PREFIX_SEPARATOR = ConfigValues.CONFIG_GROUP_PREFIX_SEPARATOR;
	public static final String CONFIG_GROUP_NAME = TasksTrackerPlugin.CONFIG_GROUP_NAME;

	private final Gson customGson;
	@Inject
	private TaskService taskService;
	@Inject
	private ConfigManager configManager;

	@Inject
	public TrackerGlobalConfigStore(Gson gson)
	{
		this.customGson = GsonFactory.newBuilder(gson).create();
	}

	// ========================================================================
	// Route Persistence
	// Routes are stored per-taskType.
	// Config key pattern: "routes-{taskType}"
	// ========================================================================

	/** Saves all routes for a given task type, replacing any existing routes. */
	public void saveRoutes(String taskType, List<CustomRoute> routes)
	{
		String key = "routes" + CONFIG_GROUP_PREFIX_SEPARATOR + taskType;
		String json = customGson.toJson(routes);
		configManager.setConfiguration(CONFIG_GROUP_NAME, key, json);
	}

	/** Loads all routes for a given task type. Returns empty list if none exist or on parse error. */
	public List<CustomRoute> loadRoutes(String taskType)
	{
		String key = "routes" + CONFIG_GROUP_PREFIX_SEPARATOR + taskType;
		String configJson = configManager.getConfiguration(CONFIG_GROUP_NAME, key);
		if (configJson == null || configJson.isEmpty())
		{
			return new ArrayList<>();
		}

		try
		{
			Type listType = TypeToken.getParameterized(ArrayList.class, CustomRoute.class).getType();
			List<CustomRoute> routes = customGson.fromJson(configJson, listType);
			if (routes == null)
			{
				return new ArrayList<>();
			}
			// Remove null routes and assign UUID to old route data
			routes.removeIf(route -> route == null);
			routes.forEach(route -> {
				if (route.getId() == null || route.getId().isEmpty())
				{
					route.setId(UUID.randomUUID().toString());
				}

				route.getSections().forEach(section -> {
					if (section.getId() == null || section.getId().isEmpty())
					{
						section.setId(UUID.randomUUID().toString());
					}
				});
			});
			saveRoutes(taskType, routes);
			return routes;
		}
		catch (JsonParseException ex)
		{
			log.error("Failed to parse routes for {}: {}", taskType, ex.getMessage());
			return new ArrayList<>();
		}
	}

	/** Adds or updates a route. If a route with the same id exists, it is replaced. */
	public void addRoute(String taskType, CustomRoute route)
	{
		if (route == null)
		{
			log.warn("Cannot add a null route");
			return;
		}
		List<CustomRoute> routes = loadRoutes(taskType);
		String routeId = route.getId();
		routes.removeIf(r -> r.getId().equals(routeId));
		routes.add(route);
		saveRoutes(taskType, routes);
	}

	/** Removes a route by id. */
	public void removeRoute(String taskType, String routeId)
	{
		if (routeId == null)
		{
			return;
		}
		List<CustomRoute> routes = loadRoutes(taskType);
		routes.removeIf(r -> routeId.equals(r.getId()));
		saveRoutes(taskType, routes);
	}

	// ========================================================================
	// Active Route Selection
	// Each tab can have a different route selected (per tab AND per taskType).
	// Stored in global config (shared across all profiles).
	// Config key pattern: "activeRoute-{tabId}-{taskType}"
	// ========================================================================

	/** Saves which route is active for a specific tab and task type. Pass null to clear. */
	public void saveActiveRouteId(ConfigValues.TaskListTabs tab, String taskType, String routeId)
	{
		String key = "activeRoute" + CONFIG_GROUP_PREFIX_SEPARATOR + tab.configID + CONFIG_GROUP_PREFIX_SEPARATOR + taskType;
		if (routeId == null || routeId.isEmpty())
		{
			configManager.unsetConfiguration(CONFIG_GROUP_NAME, key);
		}
		else
		{
			configManager.setConfiguration(CONFIG_GROUP_NAME, key, routeId);
		}
	}

	/** Loads the id of the active route for a specific tab and task type. Returns null if none. */
	public String loadActiveRouteId(ConfigValues.TaskListTabs tab, String taskType)
	{
		String key = "activeRoute" + CONFIG_GROUP_PREFIX_SEPARATOR + tab.configID + CONFIG_GROUP_PREFIX_SEPARATOR + taskType;
		String id = configManager.getConfiguration(CONFIG_GROUP_NAME, key);
		if (id == null || id.isEmpty())
		{
			return null;
		}
		return id;
	}

	/** Loads and returns the full active route object for a tab, or null if none selected. */
	public CustomRoute getActiveRoute(ConfigValues.TaskListTabs tab, String taskType)
	{
		String id = loadActiveRouteId(tab, taskType);
		if (id == null || id.isEmpty())
		{
			return null;
		}
		return loadRoutes(taskType).stream()
			.filter(r -> id.equals(r.getId()))
			.findFirst()
			.orElse(null);
	}

	// ========================================================================
	// Custom Item Completion Tracking
	// Tracks which custom items (bank stops, teleports, etc.) have been marked complete.
	// Stored in global config per taskType + routeId (shared across tabs using the same route).
	// Config key pattern: "customCompletion-{taskType}-{routeId}"
	// ========================================================================

	/** Saves the set of completed custom item IDs for a route. Pass empty/null to clear. */
	public void saveCustomItemCompletion(String taskType, String routeId, Set<String> completedIds)
	{
		String key = "customCompletion" + CONFIG_GROUP_PREFIX_SEPARATOR + taskType
			+ CONFIG_GROUP_PREFIX_SEPARATOR + routeId;
		if (completedIds == null || completedIds.isEmpty())
		{
			configManager.unsetConfiguration(CONFIG_GROUP_NAME, key);
		}
		else
		{
			String value = String.join(",", completedIds);
			configManager.setConfiguration(CONFIG_GROUP_NAME, key, value);
		}
	}

	/** Loads the set of completed custom item IDs for a route. Returns empty set if none. */
	public Set<String> loadCustomItemCompletion(String taskType, String routeId)
	{
		String key = "customCompletion" + CONFIG_GROUP_PREFIX_SEPARATOR + taskType
			+ CONFIG_GROUP_PREFIX_SEPARATOR + routeId;
		String value = configManager.getConfiguration(CONFIG_GROUP_NAME, key);
		if (value == null || value.isEmpty())
		{
			return new HashSet<>();
		}
		return new HashSet<>(Arrays.asList(value.split(",")));
	}

	/** Clears all custom item completion data for a route. */
	public void resetCustomItemCompletion(String taskType, String routeId)
	{
		saveCustomItemCompletion(taskType, routeId, null);
	}
}

