import java.nio.charset.StandardCharsets;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.reldo.taskstracker.data.jsondatastore.reader.DataStoreReader;
import net.reldo.taskstracker.data.jsondatastore.types.Manifest;

@Singleton
@Slf4j
public class ManifestClient
{
	@Inject
	private Gson gson;
	@Inject
	private DataStoreReader dataStoreReader;

	private static Manifest _manifest = null;

	public ManifestClient()
	{
		log.debug("init manifestclient");
	}

	public Manifest getManifest() throws Exception
	{
		if (_manifest != null)
		{
			return _manifest;
		}
		try (InputStream stream = this.dataStoreReader.readManifestData();
			InputStreamReader responseReader = new InputStreamReader(stream, StandardCharsets.UTF_8))
		{
			String manifestJson = CharStreams.toString(responseReader); // ew, why not a stream? not working...
			_manifest = this.gson.fromJson(manifestJson, Manifest.class);
			log.debug("_manifest = " + _manifest);
			return _manifest;
		}
	}
}

package net.reldo.taskstracker.data.jsondatastore;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.reldo.taskstracker.data.gson.GsonFactory;
import net.reldo.taskstracker.data.jsondatastore.reader.DataStoreReader;
import net.reldo.taskstracker.data.jsondatastore.types.PremadeRouteEntry;
import net.reldo.taskstracker.data.route.CustomRoute;

@Singleton
@Slf4j
public class PremadeRouteClient
{
	@Inject
	private Gson gson;
	@Inject
	private DataStoreReader dataStoreReader;

	public List<PremadeRouteEntry> getManifest() throws Exception
	{
		try (InputStream stream = this.dataStoreReader.readPremadeRouteManifest();
			InputStreamReader reader = new InputStreamReader(stream, StandardCharsets.UTF_8))
		{
			Type listType = TypeToken.getParameterized(ArrayList.class, PremadeRouteEntry.class).getType();
			List<PremadeRouteEntry> entries = this.gson.fromJson(reader, listType);
			return entries != null ? entries : new ArrayList<>();
		}
	}

	public CustomRoute getRoute(String filename) throws Exception
	{
		try (InputStream stream = this.dataStoreReader.readPremadeRoute(filename);
			InputStreamReader reader = new InputStreamReader(stream, StandardCharsets.UTF_8))
		{
			Gson routeGson = GsonFactory.newBuilder(gson).create();
			return routeGson.fromJson(reader, CustomRoute.class);
		}
	}
}

package net.reldo.taskstracker.data.jsondatastore;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import net.reldo.taskstracker.data.gson.WorldPointAdapter;
import net.runelite.api.coords.WorldPoint;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.lang.reflect.Type;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.reldo.taskstracker.data.jsondatastore.reader.DataStoreReader;
import net.reldo.taskstracker.data.jsondatastore.types.TaskDefinition;
import net.reldo.taskstracker.data.jsondatastore.types.TaskTypeDefinition;
import net.reldo.taskstracker.data.task.ITaskType;
import net.reldo.taskstracker.data.task.TaskType;
import net.runelite.api.Client;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.SpriteManager;

@Singleton
@Slf4j
public class TaskDataClient
{
	@Inject
	private ManifestClient manifestClient;
	@Inject
	private Gson gson;
	@Inject
	private DataStoreReader dataStoreReader;
	@Inject
	private Client client;
	@Inject
	private ClientThread clientThread;
	@Inject
	private SpriteManager spriteManager;

	public TaskDataClient()
	{
		log.debug("init task data client");
	}

	public HashMap<String, ITaskType> getTaskTypes() throws Exception
	{
		try (InputStream stream = this.dataStoreReader.readTaskTypes(this.manifestClient.getManifest().taskTypeMetadata);
			InputStreamReader responseReader = new InputStreamReader(stream, StandardCharsets.UTF_8))
		{
			Type listType = TypeToken.getParameterized(ArrayList.class, TaskTypeDefinition.class).getType();

			List<TaskTypeDefinition> taskTypeDefinitions = this.gson.fromJson(responseReader, listType);

			HashMap<String, ITaskType> taskTypes = new HashMap<>();
			for (TaskTypeDefinition taskTypeDefinition : taskTypeDefinitions)
			{
				taskTypes.put(taskTypeDefinition.getTaskJsonName(), new TaskType(client, clientThread, spriteManager, taskTypeDefinition));
			}
			return taskTypes;
		}
	}

	public List<TaskDefinition> getTaskDefinitions(String jsonFilename) throws Exception
	{
		try (InputStream stream = this.dataStoreReader.readTasks(jsonFilename);
			InputStreamReader responseReader = new InputStreamReader(stream, StandardCharsets.UTF_8))
		{
			Type listType = TypeToken.getParameterized(ArrayList.class, TaskDefinition.class).getType();
			Gson taskGson = this.gson.newBuilder()
				.registerTypeAdapter(WorldPoint.class, new WorldPointAdapter())
				.create();
			return taskGson.fromJson(responseReader, listType);
		}
	}
}

