package net.reldo.taskstracker.data.route;

import com.google.gson.annotations.Expose;
import lombok.Data;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;
import lombok.NonNull;

/**
 * A user-defined or imported route for completing tasks in a specific order.
 * Routes are scoped to a task type (e.g., COMBAT, EXPLORATION) and consist
 * of named sections, each containing an ordered list of tasks and custom items.
 *
 * Routes are stored per-taskType and can be selected independently per tab.
 */
@Data
public class CustomRoute
{
	/** Unique ID for this route. */
	@Expose
	@NonNull
	private String id;

	@Expose
	@NonNull
	private String name;

	/** The task type this route applies to (e.g., "COMBAT", "LEAGUE_5"). */
	@Expose
	@NonNull
	private String taskType;

	@Expose
	private String author;

	@Expose
	private String description;

	/** Ordered list of sections making up this route. */
	@Expose
	private List<RouteSection> sections;

	/** Returns all task IDs in route order, flattened across all sections. */
	public List<Integer> getFlattenedOrder()
	{
		if (sections == null)
		{
			return List.of();
		}
		return sections.stream()
			.flatMap(s -> s.getTaskIds().stream())
			.collect(Collectors.toList());
	}

	/** Returns all items (tasks and custom) in route order, flattened across all sections. */
	public List<RouteItem> getFlattenedItems()
	{
		if (sections == null)
		{
			return List.of();
		}
		return sections.stream()
			.flatMap(s -> s.getItems().stream())
			.collect(Collectors.toList());
	}

	public RouteSection getSectionForTask(int taskId)
	{
		if (sections == null)
		{
			return null;
		}
		return sections.stream()
			.filter(s -> s.containsTask(taskId))
			.findFirst()
			.orElse(null);
	}

	public int getTaskCount()
	{
		return getFlattenedOrder().size();
	}

	public int getItemCount()
	{
		return getFlattenedItems().size();
	}

	/** Returns true if the given task is the first task in its section (useful for rendering section headers). */
	public boolean isFirstTaskInSection(int taskId)
	{
		if (sections == null)
		{
			return false;
		}
		for (RouteSection section : sections)
		{
			List<Integer> ids = section.getTaskIds();
			if (!ids.isEmpty() && ids.get(0) == taskId)
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Inserts a custom item before or after the specified task.
	 * Searches all sections to find the task.
	 */
	public CustomRouteItem insertCustomItem(int taskId, CustomRouteItem customItem, boolean insertAfter)
	{
		if (sections == null)
		{
			return null;
		}
		for (RouteSection section : sections)
		{
			CustomRouteItem result = section.insertCustomItem(taskId, customItem, insertAfter);
			if (result != null)
			{
				return result;
			}
		}
		return null;
	}

	/** Returns all custom item IDs across all sections (for duplicate detection). */
	public List<String> getAllCustomItemIds()
	{
		if (sections == null)
		{
			return List.of();
		}
		List<String> ids = new ArrayList<>();
		for (RouteSection section : sections)
		{
			for (CustomRouteItem ci : section.getCustomItems())
			{
				ids.add(ci.getId());
			}
		}
		return ids;
	}

	/** Finds a custom item by its unique ID across all sections. */
	public CustomRouteItem findCustomItem(String customItemId)
	{
		if (sections == null)
		{
			return null;
		}
		for (RouteSection section : sections)
		{
			for (CustomRouteItem ci : section.getCustomItems())
			{
				if (customItemId.equals(ci.getId()))
				{
					return ci;
				}
			}
		}
		return null;
	}

	/** Removes a task by ID from whichever section contains it. Returns true if found. */
	public boolean removeTask(int taskId)
	{
		if (sections == null)
		{
			return false;
		}
		for (RouteSection section : sections)
		{
			if (section.remove(taskId))
			{
				return true;
			}
		}
		return false;
	}

	/** Removes a custom item by ID from whichever section contains it. Returns true if found. */
	public boolean removeCustomItem(String customItemId)
	{
		if (sections == null)
		{
			return false;
		}
		for (RouteSection section : sections)
		{
			if (section.removeCustomItem(customItemId))
			{
				return true;
			}
		}
		return false;
	}
	@Override
	public String toString()
	{
		return getName();
	}

}

package net.reldo.taskstracker.data.route;

import com.google.gson.annotations.Expose;
import java.util.UUID;
import lombok.Data;
import lombok.NoArgsConstructor;
import lombok.NonNull;

/**
 * Represents a non-task item in a route, such as a bank stop, teleport, or custom step.
 * Generic data model: label + icon + name, no hardcoded types.
 * Factory presets provide convenience for common items.
 */
@Data
@NoArgsConstructor
public class CustomRouteItem
{
	/** Sprite archive ID for bank map icon. */
	public static final int BANK_ICON_SPRITE = 1453;

	/** Sprite archive ID for transportation map icon. */
	public static final int TELEPORT_ICON_SPRITE = 1504;

	/** Unique identifier (8-char UUID prefix). Counterpart to structId/taskId. */
	@Expose
	@NonNull
	private String id;

	/** Primary display text (e.g., "Bank", "Teleport"). Counterpart to task name. */
	@Expose
	@NonNull
	private String label;

	/** Sprite archive ID for the icon. Counterpart to tier sprite. Null for text fallback. */
	@Expose
	private Integer icon;

	/** Detail text shown below the label. Counterpart to task description. */
	@Expose
	private String description;

	/** Returns the label for display, falling back to "Custom" if empty. */
	public String getDisplayLabel()
	{
		if (label == null || label.isEmpty())
		{
			return "Custom";
		}
		return label;
	}

	private static String generateId()
	{
		return UUID.randomUUID().toString();
	}

	public static CustomRouteItem createBank(String description)
	{
		CustomRouteItem item = new CustomRouteItem();
		item.setId(generateId());
		item.setLabel("Bank");
		item.setIcon(BANK_ICON_SPRITE);
		item.setDescription(description);
		return item;
	}

	public static CustomRouteItem createTeleport(String description)
	{
		CustomRouteItem item = new CustomRouteItem();
		item.setId(generateId());
		item.setLabel("Teleport");
		item.setIcon(TELEPORT_ICON_SPRITE);
		item.setDescription(description);
		return item;
	}

	public static CustomRouteItem createCustom(String label, String description)
	{
		CustomRouteItem item = new CustomRouteItem();
		item.setId(generateId());
		item.setLabel(label);
		item.setIcon(null);
		item.setDescription(description);
		return item;
	}
}

package net.reldo.taskstracker.data.route;

import com.google.gson.annotations.Expose;
import lombok.Data;
import net.runelite.api.coords.WorldPoint;

/**
 * A single item in a route section. Can be either a task reference (by taskId)
 * or a custom item (waypoint, reminder, etc.).
 *
 * Exactly one of taskId or customItem should be non-null.
 */
@Data
public class RouteItem
{
	/** The task ID if this item represents a task, null otherwise. */
	@Expose
	private Integer taskId;

	/** The custom item if this is not a task, null otherwise. */
	@Expose
	private CustomRouteItem customItem;

	/** Optional location data for this item (e.g., coordinates) */
	@Expose
	private WorldPoint location;

	/** Note for a route item */
	@Expose
	private String note;

	/** Returns true if this item represents a task (vs a custom item). */
	public boolean isTask()
	{
		return taskId != null;
	}

	/** Returns a unique identifier string for this item (prefixed with "task:" or "custom:"). */
	public String getItemId()
	{
		if (isTask())
		{
			return "task:" + taskId;
		}
		if (customItem != null)
		{
			return "custom:" + customItem.getId();
		}
		return "invalid";
	}

	public static RouteItem forTask(int taskId)
	{
		RouteItem item = new RouteItem();
		item.setTaskId(taskId);
		return item;
	}

	public static RouteItem forCustom(CustomRouteItem customItem)
	{
		RouteItem item = new RouteItem();
		item.setCustomItem(customItem);
		return item;
	}
}

package net.reldo.taskstracker.data.route;

import com.google.gson.Gson;
import java.awt.Toolkit;
import java.awt.datatransfer.DataFlavor;
import java.awt.datatransfer.StringSelection;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.UUID;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.JOptionPane;
import lombok.extern.slf4j.Slf4j;
import net.reldo.taskstracker.TasksTrackerConfig;
import net.reldo.taskstracker.TasksTrackerPlugin;
import net.reldo.taskstracker.config.ConfigValues;
import net.reldo.taskstracker.data.TrackerGlobalConfigStore;
import net.reldo.taskstracker.data.gson.GsonFactory;
import net.reldo.taskstracker.data.jsondatastore.PremadeRouteClient;
import net.reldo.taskstracker.data.jsondatastore.types.PremadeRouteEntry;
import net.reldo.taskstracker.data.task.TaskService;

/**
 * Manages route CRUD operations: import, export, create, delete.
 * Handles data persistence and user dialogs.
 * UI refresh is the caller's responsibility.
 * Future in-game route editing functions may also be added here.
 */
@Slf4j
@Singleton
public class RouteManager
{
	@Inject
	private Gson gson;
	@Inject
	private TasksTrackerPlugin plugin;
	@Inject
	private TaskService taskService;
	@Inject
	private TasksTrackerConfig config;
	@Inject
	private TrackerGlobalConfigStore trackerGlobalConfigStore;
	@Inject
	private PremadeRouteClient premadeRouteClient;

	/**
	 * Imports a route from the system clipboard.
	 * Shows confirmation dialog if task type mismatches.
	 * @return true if a route was imported successfully
	 */
	public boolean importRouteFromClipboard()
	{
		try
		{
			String clipboard = Toolkit.getDefaultToolkit().getSystemClipboard()
				.getData(DataFlavor.stringFlavor).toString();

			Gson routeGson = GsonFactory.newBuilder(gson).create();
			CustomRoute route = routeGson.fromJson(clipboard, CustomRoute.class);

			route = validateAndPrepareRoute(route);
			if (route == null)
			{
				return false;
			}

			saveAndActivateRoute(route);
			log.debug("Imported route: {}", route.getName());
			return true;
		}
		catch (Exception e)
		{
			log.error("Failed to import route", e);
			showErrorMessage("Failed to import route: " + e.getMessage());
			return false;
		}
	}

	/**
	 * Fetches the premade route manifest from the repository.
	 * @return list of available premade routes, filtered to current task type
	 */
	public List<PremadeRouteEntry> fetchPremadeRouteManifest() throws Exception
	{
		return premadeRouteClient.getManifest();
	}

	/**
	 * Fetches a premade route from the repository.
	 * This performs a network call and must NOT be called on the EDT.
	 * @param filename the route filename (without .json extension)
	 * @return the fetched route
	 */
	public CustomRoute fetchPremadeRoute(String filename) throws Exception
	{
		return premadeRouteClient.getRoute(filename);
	}

	/**
	 * Imports a pre-fetched route (from premade routes or any other source).
	 * Validates, saves, and activates the route. Safe to call on the EDT.
	 * @return true if the route was imported successfully
	 */
	public boolean importRoute(CustomRoute route)
	{
		try
		{
			route = validateAndPrepareRoute(route);
			if (route == null)
			{
				return false;
			}

			saveAndActivateRoute(route);
			log.debug("Imported route: {}", route.getName());
			return true;
		}
		catch (Exception e)
		{
			log.error("Failed to import route", e);
			showErrorMessage("Failed to import route: " + e.getMessage());
			return false;
		}
	}

	/**
	 * Validates and sanitizes a route for import.
	 * Checks required fields, generates missing UUIDs, handles task type mismatch,
	 * and detects/resolves duplicate IDs.
	 * @return the validated route, or null if the user cancelled a dialog
	 */
	private CustomRoute validateAndPrepareRoute(CustomRoute route) throws Exception
	{
		if (route == null)
		{
			throw new Exception("Invalid route JSON");
		}

		if (route.getName() == null || route.getName().isEmpty())
		{
			throw new Exception("Missing route name");
		}

		if (route.getTaskType() == null || route.getTaskType().isEmpty())
		{
			throw new Exception("Missing route task type");
		}

		if (route.getId() == null || route.getId().isEmpty())
		{
			route.setId(UUID.randomUUID().toString());
		}

		String currentTaskType = taskService.getCurrentTaskType().getTaskJsonName();

		if (!route.getTaskType().equals(currentTaskType))
		{
			int result = JOptionPane.showConfirmDialog(
				plugin.pluginPanel,
				"This route was created for " + route.getTaskType() +
					" but you're viewing " + currentTaskType + ".\n\nImport anyway?",
				"Task Type Mismatch",
				JOptionPane.YES_NO_OPTION,
				JOptionPane.WARNING_MESSAGE
			);
			if (result != JOptionPane.YES_OPTION)
			{
				return null;
			}
		}

		List<RouteSection> sections = route.getSections();
		for (RouteSection section : sections)
		{
			if (section.getId() == null || section.getId().isEmpty())
			{
				section.setId(UUID.randomUUID().toString());
			}

			for (RouteItem item : section.getItems())
			{
				if (!item.isTask() && item.getCustomItem() != null)
				{
					CustomRouteItem customItem = item.getCustomItem();
					if (customItem.getId() == null || customItem.getId().isEmpty())
					{
						customItem.setId(UUID.randomUUID().toString());
					}
				}
			}
		}

		route.setTaskType(currentTaskType);

		Set<CustomRouteItem> duplicateCustomItems = getDuplicateCustomRouteItems(route);
		Set<Integer> duplicateTasks = getDuplicateTaskIds(route);
		if (!duplicateCustomItems.isEmpty() || !duplicateTasks.isEmpty())
		{
			List<String> duplicateMessages = new ArrayList<>();
			duplicateMessages.add(!duplicateTasks.isEmpty() ? "task IDs" : "");
			duplicateMessages.add(!duplicateCustomItems.isEmpty() ? "custom item IDs" : "");
			String duplicatesMessage = duplicateMessages.stream()
				.filter(string -> !string.isEmpty())
				.collect(Collectors.joining(" and "));

			int result = JOptionPane.showConfirmDialog(
				plugin.pluginPanel,
				"Duplicate " + duplicatesMessage + " detected.\n"
					+ "The imported route may be different than expected.\n\n"
					+ "Import anyway?",
				"Duplicate IDs",
				JOptionPane.OK_CANCEL_OPTION,
				JOptionPane.WARNING_MESSAGE
			);
			if (result != JOptionPane.OK_OPTION)
			{
				return null;
			}
			for (Integer taskId : duplicateTasks)
			{
				log.warn("Duplicate task ID '{}' found, all later instances removed", taskId);
				RouteSection firstSection = route.getSectionForTask(taskId);
				sections.forEach(section ->
				{
					if (!section.equals(firstSection))
					{
						section.remove(taskId);
					}
				});
			}
			for (CustomRouteItem customRouteItem : duplicateCustomItems)
			{
				String newId = UUID.randomUUID().toString();
				log.warn("Duplicate custom item ID '{}' found, regenerated as '{}'", customRouteItem.getId(), newId);
				customRouteItem.setId(newId);
			}
		}

		return route;
	}

	/**
	 * Persists the route and sets it as the active route on the current tab.
	 */
	private void saveAndActivateRoute(CustomRoute route)
	{
		String taskType = taskService.getCurrentTaskType().getTaskJsonName();
		ConfigValues.TaskListTabs currentTab = config.taskListTab();
		trackerGlobalConfigStore.addRoute(taskType, route);
		trackerGlobalConfigStore.saveActiveRouteId(currentTab, taskType, route.getId());
		taskService.setActiveRoute(currentTab, route);
	}

	/**
	 * Removes a task from the active route.
	 * @param taskId the task ID to remove
	 * @return true if the task was found and removed
	 */
	public boolean removeTaskFromActiveRoute(int taskId)
	{
		CustomRoute activeRoute = taskService.getActiveRoute();
		if (activeRoute == null)
		{
			return false;
		}
		if (activeRoute.removeTask(taskId))
		{
			String taskType = taskService.getCurrentTaskType().getTaskJsonName();
			trackerGlobalConfigStore.addRoute(taskType, activeRoute);
			taskService.addRouteIndex(activeRoute);
			return true;
		}
		return false;
	}

	/**
	 * Exports the active route to the system clipboard as JSON.
	 * @return true if a route was exported
	 */
	public boolean exportActiveRoute()
	{
		ConfigValues.TaskListTabs currentTab = config.taskListTab();
		String taskType = taskService.getCurrentTaskType().getTaskJsonName();

		CustomRoute route = trackerGlobalConfigStore.getActiveRoute(currentTab, taskType);

		if (route == null)
		{
			showErrorMessage("No active route to export");
			return false;
		}

		Gson routeGson = GsonFactory.newBuilder(gson).setPrettyPrinting().create();

		String json = routeGson.toJson(route);

		StringSelection selection = new StringSelection(json);
		Toolkit.getDefaultToolkit().getSystemClipboard().setContents(selection, null);

		log.debug("Exported route to clipboard: {}", route.getName());
		return true;
	}

	/**
	 * Creates a new route from the given task IDs.
	 * Shows a dialog to enter the route name.
	 * @param visibleTaskIds ordered list of task IDs to include
	 * @return true if a route was created
	 */
	public boolean createRouteFromCurrentOrder(List<Integer> visibleTaskIds)
	{
		String name = JOptionPane.showInputDialog(
			plugin.pluginPanel,
			"Enter route name:",
			"Create Route",
			JOptionPane.PLAIN_MESSAGE
		);

		if (name == null || name.trim().isEmpty())
		{
			return false;
		}

		name = name.trim();

		if (visibleTaskIds.isEmpty())
		{
			showErrorMessage("No visible tasks to create route from");
			return false;
		}

		CustomRoute route = new CustomRoute(UUID.randomUUID().toString(), name, taskService.getCurrentTaskType().getTaskJsonName());
		route.setTaskType(taskService.getCurrentTaskType().getTaskJsonName());
		route.setAuthor("User");
		route.setDescription("Created from current task order");

		RouteSection section = new RouteSection(UUID.randomUUID().toString(), "All Tasks");
		section.setTaskIds(visibleTaskIds);

		route.setSections(List.of(section));

		ConfigValues.TaskListTabs currentTab = config.taskListTab();
		String taskType = route.getTaskType();

		trackerGlobalConfigStore.addRoute(taskType, route);
		trackerGlobalConfigStore.saveActiveRouteId(currentTab, taskType, route.getId());
		taskService.setActiveRoute(currentTab, route);

		log.debug("Created route from current order: {}", name);
		return true;
	}

	/**
	 * Deletes the active route after user confirmation.
	 * Clears the active route on all tabs that reference it.
	 * @return true if a route was deleted
	 */
	public boolean deleteActiveRoute()
	{
		ConfigValues.TaskListTabs currentTab = config.taskListTab();
		String taskType = taskService.getCurrentTaskType().getTaskJsonName();
		CustomRoute activeRoute = taskService.getActiveRoute(currentTab);

		if (activeRoute == null)
		{
			return false;
		}

		String routeId = activeRoute.getId();

		int result = JOptionPane.showConfirmDialog(
			plugin.pluginPanel,
			"Delete route \"" + activeRoute.getName() + "\"?",
			"Delete Route",
			JOptionPane.YES_NO_OPTION,
			JOptionPane.WARNING_MESSAGE
		);

		if (result != JOptionPane.YES_OPTION)
		{
			return false;
		}

		trackerGlobalConfigStore.removeRoute(taskType, routeId);

		// Clear active route on all tabs that reference the deleted route
		for (ConfigValues.TaskListTabs tab : ConfigValues.TaskListTabs.values())
		{
			String tabRouteId = trackerGlobalConfigStore.loadActiveRouteId(tab, taskType);
			if (routeId.equals(tabRouteId))
			{
				trackerGlobalConfigStore.saveActiveRouteId(tab, taskType, null);
				taskService.clearActiveRoute(tab);
			}
		}

		log.debug("Deleted route: {}", routeId);
		return true;
	}

	/**
	 * Returns a set of duplicate CustomRouteItems (by ID) found in the route.
	 * If empty, there are no duplicates.
	 */
	private Set<CustomRouteItem> getDuplicateCustomRouteItems(CustomRoute route)
	{
		Set<CustomRouteItem> duplicates = new HashSet<>();
		if (route.getSections() == null)
		{
			return duplicates;
		}
		Set<String> seenIds = new HashSet<>();
		for (RouteSection section : route.getSections())
		{
			for (RouteItem item : section.getItems())
			{
				if (!item.isTask() && item.getCustomItem() != null)
				{
					CustomRouteItem ci = item.getCustomItem();
					if (!seenIds.add(ci.getId()))
					{
						duplicates.add(ci);
					}
				}
			}
		}
		return duplicates;
	}

	/**
	 * Returns a set of duplicate tasks (by ID) found in the route.
	 * If empty, there are no duplicates.
	 */
	private Set<Integer> getDuplicateTaskIds(CustomRoute route)
	{
		Set<Integer> duplicates = new HashSet<>();
		if (route.getSections() == null)
		{
			return duplicates;
		}
		Set<Integer> seenIds = new HashSet<>();
		for (RouteSection section : route.getSections())
		{
			for (RouteItem item : section.getItems())
			{
				if (item.isTask() && item.getTaskId() != null)
				{
					Integer taskId = item.getTaskId();
					if (!seenIds.add(taskId))
					{
						duplicates.add(taskId);
					}
				}
			}
		}
		return duplicates;
	}

	private void showErrorMessage(String message)
	{
		JOptionPane.showMessageDialog(
			plugin.pluginPanel,
			message,
			"Error",
			JOptionPane.ERROR_MESSAGE
		);
	}
}

package net.reldo.taskstracker.data.route;

import com.google.gson.annotations.Expose;
import lombok.Data;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;
import lombok.NonNull;

/**
 * A named section within a route, containing an ordered list of items.
 * Sections allow routes to be organized into logical groups (e.g., by region or theme).
 *
 * When reading, the "items" format takes precedence if present.
 * When writing, only the "items" format is used (taskIds is cleared).
 */
@Data
public class RouteSection
{
	@Expose
	@NonNull
	private String id;

	@Expose
	@NonNull
	private String name;

	@Expose
	private String description;

	/** Legacy format: list of task IDs only. Prefer using items instead. */
	@Expose
	private List<Integer> taskIds;

	/** Current format: list of RouteItem (tasks and custom items interleaved). */
	@Expose
	private List<RouteItem> items;

	/**
	 * Returns all items in this section.
	 */
	public List<RouteItem> getItems()
	{
		if (items != null && !items.isEmpty())
		{
			return items;
		}
		if (taskIds != null)
		{
			setItems(taskIds.stream()
				.filter(id -> id != null)
				.map(id -> RouteItem.forTask(id))
				.collect(Collectors.toList()));

			return items;
		}
		setItems(new ArrayList<>());
		return items;
	}

	public void setItems(List<RouteItem> items)
	{
		this.items = items;
		this.taskIds = null;
	}

	/** Extracts just the task IDs from this section (ignoring custom items). */
	public List<Integer> getTaskIds()
	{
		return getItems().stream()
			.filter(RouteItem::isTask)
			.map(RouteItem::getTaskId)
			.collect(Collectors.toList());
	}

	/** Returns only the custom items (non-task items) in this section. */
	public List<CustomRouteItem> getCustomItems()
	{
		return getItems().stream()
			.filter(item -> !item.isTask())
			.map(RouteItem::getCustomItem)
			.collect(Collectors.toList());
	}

	/** Returns true if this section contains the given task ID. */
	public boolean containsTask(int taskId)
	{
		return getTaskIds().contains(taskId);
	}

	/** Returns the number of tasks (not including custom items) in this section. */
	public int getTaskCount()
	{
		return getTaskIds().size();
	}

	/** Returns the total number of items (tasks + custom items) in this section. */
	public int getItemCount()
	{
		return getItems().size();
	}

	/**
	 * Inserts a custom item before or after the specified task.
	 *
	 * @param taskId the task to insert relative to
	 * @param customItem the custom item to insert
	 * @param insertAfter true to insert after the task, false to insert before
	 * @return the inserted CustomRouteItem, or null if the task was not found
	 */
	public CustomRouteItem insertCustomItem(int taskId, CustomRouteItem customItem, boolean insertAfter)
	{
		List<RouteItem> currentItems = new ArrayList<>(getItems());
		int position = -1;

		for (int i = 0; i < currentItems.size(); i++)
		{
			RouteItem item = currentItems.get(i);
			if (item.isTask() && item.getTaskId() == taskId)
			{
				position = i;
				break;
			}
		}

		if (position == -1)
		{
			return null;
		}

		int insertPos = insertAfter ? position + 1 : position;
		currentItems.add(insertPos, RouteItem.forCustom(customItem));

		this.items = currentItems;
		this.taskIds = null;

		return customItem;
	}

	public boolean removeCustomItem(String customItemId)
	{
		if (getItems() == null)
		{
			return false;
		}
		return getItems().removeIf(item ->
			!item.isTask()
			&& item.getCustomItem() != null
			&& customItemId.equals(item.getCustomItem().getId()));
	}

	public boolean remove(Integer taskId)
	{
		if (getItems() == null)
		{
			return false;
		}
		return getItems().removeIf(item ->
			item.isTask()
				&& taskId.equals(item.getTaskId()));
	}
}

package net.reldo.taskstracker.data.route;

import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.atomic.AtomicReference;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.reldo.taskstracker.TasksTrackerConfig;
import net.runelite.api.Client;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.events.PluginMessage;

@Slf4j
@Singleton
public class ShortestPathService
{
	@Inject
	private EventBus eventBus;
	@Inject
	private Client client;
	@Inject
	private ClientThread clientThread;
	@Inject
	private TasksTrackerConfig config;

	private final AtomicReference<WorldPoint> currentGpsTarget = new AtomicReference<>(null);

	/**
	 * Updates the GPS target to the given location, or clears if null.
	 * Skips redundant updates if the target hasn't changed.
	 */
	public void setGpsTarget(WorldPoint target)
	{
		if (!config.useShortestPath() || !config.showOverlay())
		{
			clearGps();
			return;
		}

		if (target == null)
		{
			clearGps();
			return;
		}

		if (target.equals(currentGpsTarget.get()))
		{
			return;
		}

		currentGpsTarget.set(target);
		requestPath(target);
	}

	public void clearGps()
	{
		currentGpsTarget.set(null);
		eventBus.post(new PluginMessage("shortestpath", "clear"));
	}

	private void requestPath(WorldPoint target)
	{
		clientThread.invokeLater(() ->
		{
			if (client.getLocalPlayer() == null)
			{
				return;
			}

			WorldPoint playerWp = client.getLocalPlayer().getWorldLocation();
			Map<String, Object> data = new HashMap<>();
			data.put("start", playerWp);
			data.put("target", target);
			eventBus.post(new PluginMessage("shortestpath", "path", data));
		});
	}
}

