@Slf4j
public class SkillButtonFilter extends Filter
{
	private final String filterConfigKey;
	private final ConfigManager configManager;

	public SkillButtonFilter(ConfigManager configManager, String filterConfigKey)
	{
		this.configManager = configManager;
		this.filterConfigKey = filterConfigKey;
	}

	@Override
	public boolean meetsCriteria(ITask task)
	{
		String configValue = configManager.getConfiguration(TasksTrackerPlugin.CONFIG_GROUP_NAME, filterConfigKey);
		boolean isEmptyFilterSelection = configValue == null || configValue.isEmpty() || configValue.equals("-1");
		if (isEmptyFilterSelection)
		{
			return false;
		}

		List<TaskDefinitionSkill> skills = task.getTaskDefinition().getSkills();
		boolean hasNoSkills = (skills == null || skills.isEmpty());

		if (hasNoSkills)
		{
			return configValue.contains("f-NONE-f");
		}

		for (TaskDefinitionSkill skill : skills)
		{
			if (configValue.contains("f-" + skill.getSkill() + "-f"))
			{
				return true;
			}
		}
		return false;
	}
}

package net.reldo.taskstracker.data.task.filters;

/**
 * Text matching strategy. All implementations are case-insensitive.
 */
public interface TextMatcher
{
	boolean matches(String text);

	String getDescription();

	/** Returns false if the pattern failed to compile (regex only). */
	boolean isValid();

	String getErrorMessage();
}

package net.reldo.taskstracker.data.task.filters;

public class TextMatcherFactory
{
	/** Characters that trigger regex mode when auto-detection is enabled. */
	private static final String REGEX_METACHARACTERS = ".*+?[]{}()^$|\\";

	public static TextMatcher create(String pattern, boolean allowRegex)
	{
		if (pattern == null || pattern.isEmpty())
		{
			return new LiteralTextMatcher("");
		}

		if (allowRegex && containsRegexMetacharacter(pattern))
		{
			RegexTextMatcher regexMatcher = new RegexTextMatcher(pattern);
			if (regexMatcher.isValid())
			{
				return regexMatcher;
			}
			return new LiteralTextMatcher(pattern,
				"Invalid regex: " + regexMatcher.getErrorMessage() + ". Using literal search.");
		}

		return new LiteralTextMatcher(pattern);
	}

	private static boolean containsRegexMetacharacter(String pattern)
	{
		for (char c : pattern.toCharArray())
		{
			if (REGEX_METACHARACTERS.indexOf(c) != -1)
			{
				return true;
			}
		}
		return false;
	}

	public static TextMatcher createLiteral(String pattern)
	{
		return new LiteralTextMatcher(pattern);
	}

	public static TextMatcher createRegex(String pattern)
	{
		return new RegexTextMatcher(pattern);
	}
}

