package net.reldo.taskstracker.panel;

import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Dimension;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.DefaultListModel;
import javax.swing.JButton;
import javax.swing.JDialog;
import javax.swing.JLabel;
import javax.swing.JList;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.ListCellRenderer;
import javax.swing.ListSelectionModel;
import javax.swing.SwingConstants;
import net.reldo.taskstracker.data.jsondatastore.types.PremadeRouteEntry;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

public class PremadeRouteBrowserDialog
{
	/**
	 * Shows a dialog for browsing and selecting a premade route.
	 * @param parent the parent component for dialog positioning
	 * @param entries the premade route entries to display
	 * @return the selected entry, or null if the user cancelled
	 */
	public static PremadeRouteEntry show(Component parent, List<PremadeRouteEntry> entries)
	{
		DefaultListModel<PremadeRouteEntry> listModel = new DefaultListModel<>();
		entries.forEach(listModel::addElement);

		JList<PremadeRouteEntry> list = new JList<>(listModel);
		list.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
		list.setCellRenderer(new PremadeRouteListRenderer());
		list.setBackground(ColorScheme.DARKER_GRAY_COLOR);

		JScrollPane scrollPane = new JScrollPane(list);
		scrollPane.setPreferredSize(new Dimension(340, 300));

		JButton downloadButton = new JButton("Download");
		downloadButton.setEnabled(false);
		JButton cancelButton = new JButton("Cancel");

		list.addListSelectionListener(e -> {
			if (!e.getValueIsAdjusting())
			{
				downloadButton.setEnabled(list.getSelectedValue() != null);
			}
		});

		JPanel buttonPanel = new JPanel();
		buttonPanel.add(downloadButton);
		buttonPanel.add(cancelButton);

		JPanel content = new JPanel(new BorderLayout(0, 8));
		content.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));
		content.add(scrollPane, BorderLayout.CENTER);
		content.add(buttonPanel, BorderLayout.SOUTH);

		JDialog dialog = new JDialog();
		dialog.setTitle("Premade Routes");
		dialog.setModal(true);
		dialog.setContentPane(content);
		dialog.pack();
		dialog.setLocationRelativeTo(parent);
		dialog.setAlwaysOnTop(true);

		final PremadeRouteEntry[] selected = {null};

		downloadButton.addActionListener(e -> {
			selected[0] = list.getSelectedValue();
			dialog.dispose();
		});

		cancelButton.addActionListener(e -> dialog.dispose());

		// Double-click to download
		list.addMouseListener(new java.awt.event.MouseAdapter()
		{
			@Override
			public void mouseClicked(java.awt.event.MouseEvent e)
			{
				if (e.getClickCount() == 2 && list.getSelectedValue() != null)
				{
					selected[0] = list.getSelectedValue();
					dialog.dispose();
				}
			}
		});

		dialog.setVisible(true);
		return selected[0];
	}

	private static class PremadeRouteListRenderer extends JPanel implements ListCellRenderer<PremadeRouteEntry>
	{
		private final JLabel nameLabel = new JLabel();
		private final JLabel authorLabel = new JLabel();
		private final JLabel descriptionLabel = new JLabel();

		PremadeRouteListRenderer()
		{
			setLayout(new BorderLayout(0, 2));
			setBorder(BorderFactory.createEmptyBorder(6, 8, 6, 8));

			nameLabel.setFont(FontManager.getRunescapeBoldFont());
			authorLabel.setFont(FontManager.getRunescapeSmallFont());
			authorLabel.setHorizontalAlignment(SwingConstants.RIGHT);
			descriptionLabel.setFont(FontManager.getRunescapeSmallFont());
			descriptionLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

			JPanel topRow = new JPanel(new BorderLayout());
			topRow.setOpaque(false);
			topRow.add(nameLabel, BorderLayout.WEST);
			topRow.add(authorLabel, BorderLayout.EAST);

			add(topRow, BorderLayout.NORTH);
			add(descriptionLabel, BorderLayout.CENTER);
		}

		@Override
		public Component getListCellRendererComponent(JList<? extends PremadeRouteEntry> list, PremadeRouteEntry entry, int index, boolean isSelected, boolean cellHasFocus)
		{
			nameLabel.setText(entry.getName());
			authorLabel.setText(entry.getAuthor() != null ? "by " + entry.getAuthor() : "");
			descriptionLabel.setText(entry.getDescription() != null ? entry.getDescription() : "");

			if (isSelected)
			{
				setBackground(ColorScheme.MEDIUM_GRAY_COLOR);
				nameLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
				authorLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			}
			else
			{
				setBackground(index % 2 == 0 ? ColorScheme.DARKER_GRAY_COLOR : ColorScheme.DARK_GRAY_COLOR);
				nameLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
				authorLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR.darker());
			}

			return this;
		}
	}
}

package net.reldo.taskstracker.panel;

import java.awt.Dimension;
import java.util.List;
import java.util.stream.Collectors;
import javax.swing.BoxLayout;
import javax.swing.Icon;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.reldo.taskstracker.TasksTrackerConfig;
import net.reldo.taskstracker.TasksTrackerPlugin;
import net.reldo.taskstracker.config.ConfigValues;
import net.reldo.taskstracker.data.task.TaskService;
import net.reldo.taskstracker.panel.components.FixedWidthPanel;
import net.reldo.taskstracker.panel.components.MultiToggleButton;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.util.SwingUtil;

@Slf4j
public class SortPanel extends FixedWidthPanel
{
	public static final String DEFAULT_OPTION = "Default";
	public static final String ROUTE_OPTION = "Route";
	private static final String ROUTE_INFO_TOOLTIP =
		"<html>Route Mode orders tasks by sections defined in the selected route.<br>" +
		"Import routes from clipboard or create one from your current task order<br>" +
		"using the manage button (...).<br><br>" +
		"Route Designer: coming soon</html>";

	private final TasksTrackerConfig config;
	private final TaskService taskService;
	private final TaskListPanel taskListPanel;
	private final ConfigManager configManager;
	private JComboBox<String> sortDropdown;
	private MultiToggleButton directionButton;
	private JLabel routeInfoLabel;

	private Runnable sortChangeCallback;
	private boolean isSuppressingActionListener = false;

	public SortPanel(ConfigManager configManager, TasksTrackerConfig config, TaskService taskService, TaskListPanel taskListPanel)
	{
		this.config = config;
		this.configManager = configManager;
		this.taskService = taskService;
		this.taskListPanel = taskListPanel;

		setLayout(new BoxLayout(this, BoxLayout.X_AXIS));
		setAlignmentX(LEFT_ALIGNMENT);
	}

	public void setSortChangeCallback(Runnable callback)
	{
		this.sortChangeCallback = callback;
	}

	public void redraw()
	{
		removeAll();

		List<String> criteriaList = taskService.getSortedIndexes().keySet().stream()
			.sorted()
			.map((str) -> str.substring(0, 1).toUpperCase() + str.substring(1))
			.collect(Collectors.toList());
		criteriaList.add(0, DEFAULT_OPTION);
		criteriaList.add(1, ROUTE_OPTION);

		String[] criteriaArray = criteriaList.toArray(new String[0]);
		sortDropdown = new JComboBox<>(criteriaArray);
		sortDropdown.setAlignmentX(LEFT_ALIGNMENT);

		// Restore saved sort criteria from per-tab config (fallback to global)
		String tabId = config.taskListTab().configID;
		String savedCriteria = configManager.getConfiguration(TasksTrackerPlugin.CONFIG_GROUP_NAME, tabId + "SortCriteria");
		if (savedCriteria == null)
		{
			savedCriteria = config.sortCriteria();
		}
		int selectedIndex = 0;
		for (int i = 0; i < criteriaArray.length; i++)
		{
			if (criteriaArray[i].equalsIgnoreCase(savedCriteria))
			{
				selectedIndex = i;
				break;
			}
		}
		sortDropdown.setSelectedIndex(selectedIndex);

		sortDropdown.addActionListener(e -> {
			if (isSuppressingActionListener)
			{
				return;
			}
			updateConfig();
			updateRouteInfoVisibility();
			SwingUtilities.invokeLater(taskListPanel::redraw);
			if (sortChangeCallback != null)
			{
				sortChangeCallback.run();
			}
		});
		sortDropdown.setFocusable(false);

		directionButton = new MultiToggleButton(2);
		SwingUtil.removeButtonDecorations(directionButton);
		directionButton.setIcons(new Icon[]{Icons.ASCENDING_ICON, Icons.DESCENDING_ICON});
		directionButton.setToolTips(new String[]{"Ascending", "Descending"});
		directionButton.setBackground(ColorScheme.DARK_GRAY_COLOR);
		directionButton.setStateChangedAction(e -> {
			updateConfig();
			SwingUtilities.invokeLater(taskListPanel::redraw);
		});

		routeInfoLabel = new JLabel("i");
		routeInfoLabel.setFont(FontManager.getDefaultBoldFont());
		routeInfoLabel.setToolTipText(ROUTE_INFO_TOOLTIP);
		routeInfoLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		routeInfoLabel.setPreferredSize(new Dimension(24, 24));
		routeInfoLabel.setHorizontalAlignment(JLabel.CENTER);
		routeInfoLabel.setVisible(false);

		add(sortDropdown);
		add(directionButton);
		add(routeInfoLabel);
		updateRouteInfoVisibility();
	}

	private void updateRouteInfoVisibility()
	{
		boolean isRoute = isRouteMode();
		directionButton.setVisible(!isRoute);
		routeInfoLabel.setVisible(isRoute);
	}

	/**
	 * Refreshes the sort dropdown and direction button from the current tab's config
	 * without rebuilding all components. Called on tab change.
	 */
	public void refreshFromConfig()
	{
		if (sortDropdown == null)
		{
			return;
		}

		String tabId = config.taskListTab().configID;
		String savedCriteria = configManager.getConfiguration(TasksTrackerPlugin.CONFIG_GROUP_NAME, tabId + "SortCriteria");
		if (savedCriteria == null)
		{
			savedCriteria = "default";
		}

		// Suppress action listener while we programmatically update the dropdown
		isSuppressingActionListener = true;
		for (int i = 0; i < sortDropdown.getItemCount(); i++)
		{
			if (sortDropdown.getItemAt(i).equalsIgnoreCase(savedCriteria))
			{
				sortDropdown.setSelectedIndex(i);
				break;
			}
		}

		// Restore direction
		String savedDirection = configManager.getConfiguration(TasksTrackerPlugin.CONFIG_GROUP_NAME, tabId + "SortDirection");
		if (savedDirection != null)
		{
			try
			{
				ConfigValues.SortDirections dir = ConfigValues.SortDirections.valueOf(savedDirection);
				directionButton.setState(dir.ordinal());
			}
			catch (IllegalArgumentException ignored)
			{
			}
		}
		isSuppressingActionListener = false;

		// Write the restored values to global config so TaskListPanel reads the right values
		updateConfig();
		updateRouteInfoVisibility();
	}

	public boolean isRouteMode()
	{
		if (sortDropdown == null)
		{
			return false;
		}
		String selected = (String) sortDropdown.getSelectedItem();
		return ROUTE_OPTION.equals(selected);
	}

	protected void updateConfig()
	{
		String criteria = sortDropdown.getItemAt(sortDropdown.getSelectedIndex()).toLowerCase();
		ConfigValues.SortDirections direction = ConfigValues.SortDirections.values()[directionButton.getState()];
		String tabId = config.taskListTab().configID;

		log.debug("updateConfig {}, {}, {}", TasksTrackerPlugin.CONFIG_GROUP_NAME, tabId + "SortCriteria", criteria);

		// Save per-tab sort config
		configManager.setConfiguration(TasksTrackerPlugin.CONFIG_GROUP_NAME, tabId + "SortCriteria", criteria);
		configManager.setConfiguration(TasksTrackerPlugin.CONFIG_GROUP_NAME, tabId + "SortDirection", direction);

		// Also write global keys (TaskListPanel reads these for rendering)
		configManager.setConfiguration(TasksTrackerPlugin.CONFIG_GROUP_NAME, "sortCriteria", criteria);
		configManager.setConfiguration(TasksTrackerPlugin.CONFIG_GROUP_NAME, "sortDirection", direction);
	}
}

package net.reldo.taskstracker.panel;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import javax.swing.BoxLayout;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import lombok.extern.slf4j.Slf4j;
import net.reldo.taskstracker.TasksTrackerPlugin;
import net.reldo.taskstracker.data.jsondatastore.types.FilterConfig;
import net.reldo.taskstracker.data.jsondatastore.types.FilterValueType;
import net.reldo.taskstracker.data.task.TaskService;
import net.reldo.taskstracker.panel.components.FixedWidthPanel;
import net.reldo.taskstracker.panel.filters.ComboItem;
import net.reldo.taskstracker.panel.filters.DynamicButtonFilterPanel;
import net.reldo.taskstracker.panel.filters.DynamicDropdownFilterPanel;
import net.reldo.taskstracker.panel.filters.FilterPanel;
import net.reldo.taskstracker.panel.filters.SkillButtonFilterPanel;
import net.runelite.client.ui.ColorScheme;

@Slf4j
public class SubFilterPanel extends FixedWidthPanel
{
	private final List<FilterPanel> filterPanels = new ArrayList<>();
	private TasksTrackerPlugin plugin;
	private TaskService taskService;

	public SubFilterPanel(TasksTrackerPlugin plugin, TaskService taskService)
	{
		this.plugin = plugin;
		this.taskService = taskService;
		log.debug("SubFilterPanel.constructor");
		setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
		setBorder(new EmptyBorder(0, 0, 0, 0));
		setBackground(ColorScheme.DARKER_GRAY_COLOR);
		setVisible(false);
	}

	public void redraw()
	{
		log.debug("SubFilterPanel.redraw"); // TODO: figure out why this calls multiple times upon switching task type

		removeAll();

		filterPanels.clear();
		filterPanels.addAll(getFilterPanels(taskService.getCurrentTaskType().getFilters()));
		filterPanels.forEach((filterPanel) -> {
			add(filterPanel);
			filterPanel.redraw();
		});
	}

	private List<FilterPanel> getFilterPanels(ArrayList<FilterConfig> filterConfigs)
	{
		List<FilterPanel> filterPanels = new ArrayList<>();
		for (FilterConfig filterConfig : filterConfigs)
		{
			try
			{
				FilterPanel filterPanel = createDynamicFilterPanel(filterConfig);
				if (filterPanel == null)
				{
					continue;
				}
				filterPanels.add(filterPanel);
			}
			catch (Exception ex)
			{
				log.error("error creating filter panel {} {}", filterConfig.getConfigKey(), ex);
			}
		}
		return filterPanels;
	}

	private FilterPanel createDynamicFilterPanel(FilterConfig filterConfig) throws Exception
	{
		if (filterConfig.getFilterType() == null)
		{
			log.warn("Skipping filter panel for {} - filterType is null", filterConfig.getConfigKey());
			return null;
		}
		switch (filterConfig.getFilterType())
		{
			case BUTTON_FILTER:
				if (filterConfig.getValueType() == FilterValueType.SKILL || filterConfig.getConfigKey().equals("skill"))
				{
					return new SkillButtonFilterPanel(plugin, filterConfig, taskService.getCurrentTaskType());
				}
				return new DynamicButtonFilterPanel(plugin, filterConfig, taskService.getCurrentTaskType());
			case DROPDOWN_FILTER:
				ComboItem[] dropdownItems = getDropdownItems(filterConfig);
				DynamicDropdownFilterPanel dropdownPanel = new DynamicDropdownFilterPanel(plugin, filterConfig, taskService.getCurrentTaskType(), dropdownItems);
				populateDropdownItemsAsync(filterConfig, dropdownPanel);
				return dropdownPanel;
			default:
				log.error("invalid filter type " + filterConfig.getFilterType());
				return null;
		}
	}

	private ComboItem[] getDropdownItems(FilterConfig filterConfig)
	{
		if (filterConfig.getValueType() == null)
		{
			throw new Error("invalid filterConfig for dropdown items");
		}
		if (filterConfig.getValueType().equals(FilterValueType.PARAM_INTEGER) && !filterConfig.getOptionLabelEnum().isEmpty())
		{
			ArrayList<ComboItem<Integer>> options = new ArrayList<>();
			options.add(new ComboItem<>(-1, ""));
			return options.toArray(new ComboItem[0]);
		}

		return new ComboItem[0];
	}

	private void populateDropdownItemsAsync(FilterConfig filterConfig, DynamicDropdownFilterPanel dropdownPanel)
	{
		if (filterConfig.getValueType() != FilterValueType.PARAM_INTEGER)
		{
			return;
		}
		String enumName = filterConfig.getOptionLabelEnum();
		if (enumName == null || enumName.isEmpty())
		{
			return;
		}

		taskService.getStringEnumValuesAsync(enumName).thenAccept(enumEntries -> {
			ArrayList<ComboItem<Integer>> options = new ArrayList<>();
			options.add(new ComboItem<>(-1, ""));
			for (Map.Entry<Integer, String> entry : enumEntries.entrySet())
			{
				if (filterConfig.getValueName().equals("tier"))
				{
					if (entry.getValue().equals("All") || entry.getValue().equals("Tier"))
					{
						continue;
					}
				}
				options.add(new ComboItem<>(entry.getKey(), entry.getValue()));
			}
			SwingUtilities.invokeLater(() -> dropdownPanel.setItems(options.toArray(new ComboItem[0])));
		}).exceptionally(ex -> {
			log.error("error populating dropdown items for {}", filterConfig.getConfigKey(), ex);
			return null;
		});
	}
}

package net.reldo.taskstracker.panel;

import java.awt.Component;
