package net.reldo.taskstracker.panel.components;

import java.awt.event.ActionEvent;
import java.awt.event.ActionListener;
import java.awt.event.MouseEvent;
import javax.swing.Icon;
import javax.swing.JButton;
import javax.swing.JMenuItem;
import javax.swing.JPopupMenu;
import javax.swing.border.EmptyBorder;
import lombok.Getter;
import lombok.Setter;

public class MultiToggleButton extends JButton
{

	// Icons
	private final Icon[] icons;
	// Tooltips
	private final String[] tooltips;
	private final int stateCount;
	@Setter
	private ActionListener stateChangedAction = null;
	@Getter
	private int state = 0;
	final JPopupMenu lockedPopupMenu = new JPopupMenu();
	final JPopupMenu popupMenu = new JPopupMenu();
	private boolean popupMenuEnabled = false;

	public MultiToggleButton(int stateCount)
	{
		super();
		this.stateCount = stateCount;
		icons = new Icon[stateCount];
		tooltips = new String[stateCount];
		popupMenu.setBorder(new EmptyBorder(5, 5, 5, 5));
		addActionListener(e -> changeStateThenAction());
		super.setToolTipText("Initial State"); // Tooltip text must be initialised for getToolTipText() to be called

		lockedPopupMenu.setBorder(new EmptyBorder(5, 5, 5, 5));
		JMenuItem menuItem = new JMenuItem("\uD83D\uDD12 Locked");
		menuItem.setEnabled(false);
		lockedPopupMenu.add(menuItem);
	}

	public void popupMenuEnabled(boolean enabled)
	{
		if (popupMenuEnabled != enabled)
		{
			popupMenuEnabled = enabled;
			if (popupMenuEnabled)
			{
				this.setComponentPopupMenu(popupMenu);
			}
			else
			{
				this.setComponentPopupMenu(lockedPopupMenu);
			}
		}
	}

	public void setIcon(Icon icon, int state)
	{
		if (state < 0 || state > stateCount || icon == null)
		{
			return;
		}

		icons[state] = icon;

		if (state == this.state)
		{
			setIconState();
		}
	}

	public boolean setIcons(Icon[] icons)
	{
		if (icons == null || icons.length == 0)
		{
			return false;
		}

		for (int i = 0; i < icons.length; i++)
		{
			setIcon(icons[i], i);
		}

		return true;
	}

	public void setToolTip(String tooltip, int state)
	{
		if (state < 0 || state > 3 || tooltip == null)
		{
			return;
		}

		tooltips[state] = tooltip;
		addPopupMenuItem(tooltip, state);
	}

	public boolean setToolTips(String[] tooltips)
	{
		if (tooltips == null || tooltips.length == 0)
		{
			return false;
		}

		for (int i = 0; i < tooltips.length; i++)
		{
			setToolTip(tooltips[i], i);
		}

		return true;
	}

	public void changeState()
	{
		setState((++state) % stateCount);
	}

	public void changeStateThenAction()
	{
		setStateThenAction((++state) % stateCount);
	}

	private void setIconState()
	{
		super.setIcon(icons[state]);
	}

	private String createToolTipText()
	{
		String tooltipText = tooltips[state];

		if (!this.isEnabled())
		{
			tooltipText = "\uD83D\uDD12 " + tooltipText;//"🔒 "
		}

		return tooltipText;
	}

	@Override
	public String getToolTipText(MouseEvent mouseEvent)
	{
		return createToolTipText();
	}

	public void setState(int state)
	{
		this.state = state;
		setIconState();
	}

	public void setStateThenAction(int state)
	{
		setState(state);
		if (stateChangedAction != null)
		{
			this.stateChangedAction.actionPerformed(new ActionEvent(this, 0, ""));
		}
	}

	private void addPopupMenuItem(String text, int state)
	{
		JMenuItem menuItem = new JMenuItem(text);
		menuItem.addActionListener(e -> {
			if (isEnabled())
			{
				setStateThenAction(state);
			}
		});
		popupMenu.add(menuItem);
	}

	public void setEnabled(boolean enabled)
	{
		super.setEnabled(enabled);
		popupMenuEnabled(enabled);
	}
}

package net.reldo.taskstracker.panel.components;

import java.awt.BorderLayout;
import java.awt.Dimension;
import java.awt.event.ActionListener;
import java.util.List;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import net.reldo.taskstracker.data.route.CustomRoute;
import net.runelite.client.ui.ColorScheme;

public class RouteSelector extends JPanel
{
	public static final CustomRoute NO_ROUTE_OPTION = new CustomRoute("ThisIsNotARoute", "(none)", "AllTaskTypes" );

	private final JComboBox<CustomRoute> routeDropdown;
	private final JButton manageButton;
	private boolean isUpdating = false;

	public RouteSelector()
	{
		setLayout(new BorderLayout(5, 0));
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		JLabel label = new JLabel(" L");
		label.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

		routeDropdown = new JComboBox<>();
		routeDropdown.setToolTipText("Select active route");
		routeDropdown.setFocusable(false);
		routeDropdown.setPreferredSize(new Dimension(150, 25));

		manageButton = new JButton("...");
		manageButton.setToolTipText("Manage routes");
		manageButton.setFocusable(false);
		manageButton.setPreferredSize(new Dimension(30, 25));

		add(label, BorderLayout.WEST);
		add(routeDropdown, BorderLayout.CENTER);
		add(manageButton, BorderLayout.EAST);
	}

	public void setRoutes(List<CustomRoute> routes, String activeRouteId)
	{
		isUpdating = true;
		try
		{
			routeDropdown.removeAllItems();
			routeDropdown.addItem(NO_ROUTE_OPTION);

			if (routes != null)
			{
				for (CustomRoute route : routes)
				{
					routeDropdown.addItem(route);
				}

				routes.stream()
					.filter(route -> route.getId().equals(activeRouteId))
					.findFirst()
					.ifPresentOrElse(routeDropdown::setSelectedItem, () -> routeDropdown.setSelectedItem(NO_ROUTE_OPTION));
			}
			else
			{
				routeDropdown.setSelectedIndex(0);
			}
		}
		finally
		{
			isUpdating = false;
		}
	}

	public CustomRoute getSelectedRoute()
	{
		CustomRoute selected = (CustomRoute) routeDropdown.getSelectedItem();
		return NO_ROUTE_OPTION.equals(selected) ? null : selected;
	}

	public String getSelectedRouteId()
	{
		CustomRoute selected = (CustomRoute) routeDropdown.getSelectedItem();
		return (selected == null || NO_ROUTE_OPTION.equals(selected)) ? null : selected.getId();
	}

	public String getSelectedRouteName()
	{
		CustomRoute selected = (CustomRoute) routeDropdown.getSelectedItem();
		return (selected == null || NO_ROUTE_OPTION.equals(selected)) ? null : selected.getName();
	}

	public void addRouteChangeListener(ActionListener listener)
	{
		routeDropdown.addActionListener(e -> {
			if (!isUpdating)
			{
				listener.actionPerformed(e);
			}
		});
	}

	public void addManageListener(ActionListener listener)
	{
		manageButton.addActionListener(listener);
	}
}

